import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  Trello, Users, AlertCircle, CheckSquare, ListTodo,
  TrendingUp, Clock, Calendar, ArrowRight
} from "lucide-react";
import { useAuth } from "../context/AuthContext";
import { useWorkspace } from "../context/WorkspaceContext";
import api from "../utils/api";

const PRIORITY_COLORS = {
  critical: { fill: "#ef4444", text: "text-red-400", bg: "bg-red-500/10", border: "border-red-500/20" },
  high: { fill: "#f97316", text: "text-orange-400", bg: "bg-orange-500/10", border: "border-orange-500/20" },
  medium: { fill: "#eab308", text: "text-yellow-400", bg: "bg-yellow-500/10", border: "border-yellow-500/20" },
  low: { fill: "#3b82f6", text: "text-blue-400", bg: "bg-blue-500/10", border: "border-blue-500/20" },
  none: { fill: "#64748b", text: "text-slate-400", bg: "bg-slate-500/10", border: "border-slate-500/20" }
};

// Simple Avatar Component for Assignee Loads
const MemberAvatar = ({ name, avatar, color }) => {
  const initials = name
    ? name.split(" ").map((n) => n[0]).slice(0, 2).join("").toUpperCase()
    : "?";

  if (avatar) {
    return <img src={avatar} alt={name} className="w-8 h-8 rounded-full object-cover flex-shrink-0" />;
  }
  return (
    <div
      className="w-8 h-8 rounded-full flex items-center justify-center font-semibold text-white text-xs flex-shrink-0"
      style={{ backgroundColor: color || "#6366f1" }}
    >
      {initials}
    </div>
  );
};

const HomePage = () => {
  const { user } = useAuth();
  const { activeWorkspace, fetchWorkspaces } = useWorkspace();
  const navigate = useNavigate();

  const [analytics, setAnalytics] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Invitations state
  const [invitations, setInvitations] = useState([]);
  const [loadingInvites, setLoadingInvites] = useState(false);

  const fetchInvitations = async () => {
    setLoadingInvites(true);
    try {
      const { data } = await api.get("/workspaces/invitations");
      setInvitations(data.invitations || []);
    } catch (err) {
      console.error("Failed to fetch invitations", err);
    } finally {
      setLoadingInvites(false);
    }
  };

  const fetchAnalytics = async () => {
    if (!activeWorkspace) return;
    setLoading(true);
    setError(null);
    try {
      const { data } = await api.get(`/workspaces/${activeWorkspace._id}/analytics`);
      setAnalytics(data.analytics);
    } catch (err) {
      console.error("Failed to fetch workspace analytics", err);
      setError("Failed to load analytics data.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchWorkspaces();
    fetchInvitations();
  }, []);

  useEffect(() => {
    fetchAnalytics();
  }, [activeWorkspace]);

  const handleAcceptInvite = async (token) => {
    try {
      await api.post(`/workspaces/accept-invite/${token}`);
      await fetchWorkspaces();
      await fetchInvitations();
    } catch (err) {
      console.error("Failed to accept invitation", err);
      alert(err.response?.data?.message || "Failed to accept invitation");
    }
  };

  const handleRejectInvite = async (token) => {
    try {
      await api.post(`/workspaces/reject-invite/${token}`);
      await fetchInvitations();
    } catch (err) {
      console.error("Failed to reject invitation", err);
      alert(err.response?.data?.message || "Failed to reject invitation");
    }
  };

  const firstName = user?.name?.split(" ")[0] || "there";
  const hour = new Date().getHours();
  const greeting = hour < 12 ? "Good morning" : hour < 17 ? "Good afternoon" : "Good evening";

  // Priority SVG Donut calculations
  const renderPriorityDonut = () => {
    if (!analytics || !analytics.priorityDistribution) return null;
    const dist = analytics.priorityDistribution;
    const total = Object.values(dist).reduce((a, b) => a + b, 0);

    if (total === 0) {
      return (
        <div className="flex flex-col items-center justify-center h-48 text-slate-500">
          <CheckSquare size={32} className="mb-2 opacity-50" />
          <span className="text-xs">No tasks to analyze priority</span>
        </div>
      );
    }

    const radius = 40;
    const strokeWidth = 10;
    const circumference = 2 * Math.PI * radius;
    let accumulatedOffset = 0;

    const segments = Object.entries(dist)
      .filter(([_, val]) => val > 0)
      .map(([key, val]) => {
        const percentage = val / total;
        const strokeLength = percentage * circumference;
        const offset = circumference - strokeLength + accumulatedOffset;
        accumulatedOffset += strokeLength;

        return {
          key,
          val,
          color: PRIORITY_COLORS[key].fill,
          strokeDasharray: `${strokeLength} ${circumference}`,
          strokeDashoffset: offset,
          percentage: Math.round(percentage * 100)
        };
      });

    return (
      <div className="flex items-center gap-6">
        <div className="relative w-36 h-36 flex-shrink-0">
          <svg viewBox="0 0 100 100" className="w-full h-full transform -rotate-90">
            <circle
              cx="50"
              cy="50"
              r={radius}
              fill="transparent"
              stroke="#1e293b"
              strokeWidth={strokeWidth}
            />
            {segments.map((seg) => (
              <circle
                key={seg.key}
                cx="50"
                cy="50"
                r={radius}
                fill="transparent"
                stroke={seg.color}
                strokeWidth={strokeWidth}
                strokeDasharray={seg.strokeDasharray}
                strokeDashoffset={seg.strokeDashoffset}
                className="transition-all duration-300"
              />
            ))}
          </svg>
          <div className="absolute inset-0 flex flex-col items-center justify-center">
            <span className="text-xl font-bold text-white">{total}</span>
            <span className="text-[10px] text-slate-500 uppercase tracking-wider">Cards</span>
          </div>
        </div>
        <div className="flex-1 flex flex-col gap-2">
          {Object.entries(dist).map(([key, val]) => {
            if (val === 0) return null;
            const pct = Math.round((val / total) * 100);
            return (
              <div key={key} className="flex items-center justify-between text-xs">
                <div className="flex items-center gap-2">
                  <span className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: PRIORITY_COLORS[key].fill }} />
                  <span className="capitalize text-slate-300">{key}</span>
                </div>
                <div className="flex gap-2 items-center text-right font-medium">
                  <span className="text-slate-400">{val}</span>
                  <span className="text-slate-500 w-8">({pct}%)</span>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <div className="px-8 py-8 max-w-5xl mx-auto">
      {/* Greeting */}
      <div className="mb-10 flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-white mb-1">
            {greeting}, {firstName} 👋
          </h1>
          <p className="text-slate-400">
            {activeWorkspace
              ? `Here's what's happening in ${activeWorkspace.name}`
              : "Create or join a workspace to get started."}
          </p>
        </div>
        {activeWorkspace && (
          <button
            onClick={() => navigate("/boards")}
            className="flex items-center gap-2 px-4 py-2 bg-slate-800/80 hover:bg-slate-700/80
              border border-slate-700/60 hover:border-violet-500/40 text-slate-200 hover:text-white
              rounded-xl text-sm font-semibold transition-all duration-200 shadow-sm"
          >
            <span>View Boards</span>
            <ArrowRight size={15} />
          </button>
        )}
      </div>

      {/* Invitations list */}
      {invitations.length > 0 && (
        <div className="mb-8 bg-violet-950/20 border border-violet-800/40 rounded-3xl p-6">
          <h2 className="text-lg font-bold text-white mb-2 flex items-center gap-2">
            ✉️ Workspace Invitations
          </h2>
          <p className="text-sm text-slate-400 mb-4">
            You have been invited to join the following workspaces.
          </p>
          <div className="flex flex-col gap-3">
            {invitations.map((inv) => (
              <div
                key={inv.inviteToken}
                className="flex flex-wrap items-center justify-between gap-4 bg-slate-900/60 border border-slate-800/80 rounded-2xl p-4"
              >
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-xl bg-slate-800 flex items-center justify-center text-lg">
                    {inv.icon || "🏢"}
                  </div>
                  <div>
                    <h3 className="text-sm font-semibold text-white">
                      {inv.name}
                    </h3>
                    <p className="text-xs text-slate-500">
                      Invited as <span className="text-violet-400 capitalize">{inv.role}</span> by {inv.owner?.name || "Workspace Owner"} ({inv.owner?.email})
                    </p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => handleAcceptInvite(inv.inviteToken)}
                    className="px-4 py-2 rounded-xl bg-violet-600 hover:bg-violet-500 text-white text-xs font-semibold transition-colors"
                  >
                    Accept
                  </button>
                  <button
                    onClick={() => handleRejectInvite(inv.inviteToken)}
                    className="px-4 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-semibold transition-colors"
                  >
                    Decline
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeWorkspace ? (
        loading ? (
          <div className="space-y-6">
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 animate-pulse">
              {[...Array(4)].map((_, i) => (
                <div key={i} className="h-24 bg-slate-800/40 border border-slate-800/50 rounded-2xl" />
              ))}
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-pulse">
              <div className="h-64 bg-slate-800/40 border border-slate-800/50 rounded-3xl" />
              <div className="h-64 bg-slate-800/40 border border-slate-800/50 rounded-3xl" />
            </div>
          </div>
        ) : error ? (
          <div className="flex flex-col items-center justify-center py-20 text-center text-rose-400 bg-rose-950/5 border border-rose-900/30 rounded-3xl p-8">
            <AlertCircle size={40} className="mb-4" />
            <h3 className="text-lg font-semibold mb-2">Error loading analytics</h3>
            <p className="text-slate-400 text-sm mb-4">{error}</p>
            <button onClick={fetchAnalytics} className="px-4 py-2 bg-slate-800 hover:bg-slate-700 rounded-xl text-white text-sm">
              Try Again
            </button>
          </div>
        ) : analytics ? (
          <div className="space-y-8">
            {/* Stats Overview */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
              {[
                {
                  label: "Total Boards",
                  value: analytics.stats.totalBoards,
                  icon: Trello,
                  colorClass: "text-violet-400 bg-violet-500/10 border-violet-500/20"
                },
                {
                  label: "Active Cards",
                  value: analytics.stats.totalCards,
                  icon: CheckSquare,
                  colorClass: "text-emerald-400 bg-emerald-500/10 border-emerald-500/20"
                },
                {
                  label: "Workspace Members",
                  value: analytics.stats.totalMembers,
                  icon: Users,
                  colorClass: "text-blue-400 bg-blue-500/10 border-blue-500/20"
                },
                {
                  label: "Overdue Tasks",
                  value: analytics.stats.overdueCount,
                  icon: AlertCircle,
                  colorClass: `text-red-400 bg-red-500/10 border-red-500/20 ${analytics.stats.overdueCount > 0 ? "animate-pulse shadow-lg shadow-red-500/5" : ""}`
                }
              ].map((stat, i) => (
                <div
                  key={i}
                  className="bg-slate-900/50 border border-slate-800/80 rounded-2xl p-5 flex items-center justify-between
                    hover:scale-[1.02] hover:bg-slate-900/80 transition-all duration-200 group"
                >
                  <div>
                    <span className="text-xs text-slate-500 uppercase tracking-wider font-semibold">{stat.label}</span>
                    <h2 className="text-3xl font-bold text-white mt-1 group-hover:text-violet-300 transition-colors">{stat.value}</h2>
                  </div>
                  <div className={`p-3 rounded-xl border ${stat.colorClass} flex items-center justify-center`}>
                    <stat.icon size={20} />
                  </div>
                </div>
              ))}
            </div>

            {/* Middle Analytics charts */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Priorities distribution */}
              <div className="bg-slate-900/40 border border-slate-800/80 rounded-3xl p-6">
                <div className="flex items-center gap-2 mb-6">
                  <TrendingUp size={18} className="text-violet-400" />
                  <h3 className="text-sm font-bold text-white uppercase tracking-wider">Card Priorities</h3>
                </div>
                {renderPriorityDonut()}
              </div>

              {/* Status List distribution */}
              <div className="bg-slate-900/40 border border-slate-800/80 rounded-3xl p-6">
                <div className="flex items-center gap-2 mb-6">
                  <ListTodo size={18} className="text-violet-400" />
                  <h3 className="text-sm font-bold text-white uppercase tracking-wider">Status Distribution</h3>
                </div>
                {Object.keys(analytics.listDistribution).length === 0 ? (
                  <div className="flex flex-col items-center justify-center h-48 text-slate-500">
                    <ListTodo size={32} className="mb-2 opacity-50" />
                    <span className="text-xs">No status data to analyze</span>
                  </div>
                ) : (
                  <div className="flex flex-col gap-4 max-h-52 overflow-y-auto pr-1">
                    {Object.entries(analytics.listDistribution).map(([label, value]) => {
                      const maxVal = Math.max(...Object.values(analytics.listDistribution), 1);
                      const percentage = (value / maxVal) * 100;
                      return (
                        <div key={label} className="flex flex-col gap-1">
                          <div className="flex justify-between text-xs">
                            <span className="text-slate-300 font-medium truncate max-w-[200px]">{label}</span>
                            <span className="text-violet-400 font-semibold">{value}</span>
                          </div>
                          <div className="h-2 w-full bg-slate-800/60 rounded-full overflow-hidden">
                            <div
                              className="h-full bg-gradient-to-r from-violet-500 to-indigo-500 rounded-full transition-all duration-500 ease-out"
                              style={{ width: `${percentage}%` }}
                            />
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>

            {/* Bottom Row: Assignee load and Overdue lists */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Member Assignee Loads */}
              <div className="bg-slate-900/40 border border-slate-800/80 rounded-3xl p-6">
                <div className="flex items-center gap-2 mb-6">
                  <Users size={18} className="text-violet-400" />
                  <h3 className="text-sm font-bold text-white uppercase tracking-wider">Assignee Workload</h3>
                </div>
                {analytics.assigneeLoad.length === 0 ? (
                  <div className="flex flex-col items-center justify-center h-48 text-slate-500">
                    <Users size={32} className="mb-2 opacity-50" />
                    <span className="text-xs">No members in workspace</span>
                  </div>
                ) : (
                  <div className="flex flex-col gap-4 max-h-64 overflow-y-auto pr-1">
                    {analytics.assigneeLoad.map((member) => {
                      const maxCards = Math.max(...analytics.assigneeLoad.map(m => m.cardCount), 1);
                      const percentage = (member.cardCount / maxCards) * 100;
                      return (
                        <div key={member._id} className="flex items-center gap-3">
                          <MemberAvatar name={member.name} avatar={member.avatar} color={member.avatarColor} />
                          <div className="flex-1 min-w-0">
                            <div className="flex justify-between items-center text-xs mb-1">
                              <span className="text-slate-200 font-medium truncate">{member.name}</span>
                              <span className="text-slate-400 font-semibold">{member.cardCount} cards</span>
                            </div>
                            <div className="h-1.5 w-full bg-slate-800/60 rounded-full overflow-hidden">
                              <div
                                className="h-full bg-gradient-to-r from-violet-500 to-fuchsia-500 rounded-full transition-all duration-500 ease-out"
                                style={{ width: `${percentage}%` }}
                              />
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>

              {/* Urgent & Overdue Task list */}
              <div className="bg-slate-900/40 border border-slate-800/80 rounded-3xl p-6">
                <div className="flex items-center gap-2 mb-6">
                  <Clock size={18} className="text-red-400" />
                  <h3 className="text-sm font-bold text-white uppercase tracking-wider">Urgent & Overdue Tasks</h3>
                </div>
                {analytics.urgentCards.length === 0 ? (
                  <div className="flex flex-col items-center justify-center h-48 text-slate-500">
                    <Clock size={32} className="mb-2 opacity-50 text-slate-600" />
                    <span className="text-xs">No urgent deadlines in sight</span>
                  </div>
                ) : (
                  <div className="flex flex-col gap-3">
                    {analytics.urgentCards.map((card) => {
                      const isOverdue = card.status === "overdue";
                      return (
                        <button
                          key={card._id}
                          onClick={() => card.board && navigate(`/boards/${card.board._id}`)}
                          className="w-full text-left p-3.5 bg-slate-900/60 border border-slate-850 hover:border-violet-500/30
                            hover:bg-slate-900/90 rounded-2xl flex flex-col sm:flex-row sm:items-center justify-between gap-3
                            transition-all duration-200 group"
                        >
                          <div className="min-w-0">
                            <h4 className="text-xs font-semibold text-slate-200 group-hover:text-white truncate transition-colors">
                              {card.title}
                            </h4>
                            <div className="flex items-center gap-1.5 text-[10.5px] text-slate-500 mt-1">
                              <Trello size={10} />
                              <span className="truncate">{card.board?.title || "Board"}</span>
                            </div>
                          </div>
                          <div className="flex items-center gap-2.5 flex-shrink-0 self-end sm:self-auto">
                            <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wider
                              ${isOverdue ? "bg-red-500/10 text-red-400 border border-red-500/20" : "bg-orange-500/10 text-orange-400 border border-orange-500/20"}`}>
                              {isOverdue ? "Overdue" : "Due Soon"}
                            </span>
                            <div className="flex items-center gap-1 text-[10px] text-slate-400">
                              <Calendar size={11} />
                              <span>{new Date(card.dueDate).toLocaleDateString(undefined, { month: "short", day: "numeric" })}</span>
                            </div>
                          </div>
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>
          </div>
        ) : null
      ) : (
        <div className="flex flex-col items-center justify-center py-20 text-center">
          <div className="w-16 h-16 rounded-2xl bg-slate-800 flex items-center justify-center text-3xl mb-4">
            🏢
          </div>
          <h3 className="text-lg font-semibold text-white mb-2">No workspace yet</h3>
          <p className="text-slate-400 text-sm mb-6 max-w-xs">
            Create or select a workspace from the sidebar to view metrics.
          </p>
        </div>
      )}
    </div>
  );
};

export default HomePage;
